reps = [
    ('> **Текущая версия кэша:** `kipia-test-v547`', '> **Текущая версия кэша:** `kipia-test-v548`'),
    ('| `kip8test` | PWA | `kipia-test-v547` |', '| `kip8test` | PWA | `kipia-test-v548` |'),
]
for old, new in reps:
    n = src.count(old)
    assert n == 1, (old, n)
    src = src.replace(old, new)
